// Generated by scripts/sync-film.mjs from motion-film/src/fx/Fire.tsx. Edit it there, then run `npm run sync:film`.
import React from "react";
import { random } from "remotion";
import { palette } from "../theme/palette";

/**
 * Stylised sacred fire: three tongues per layer, three layers (outer → core).
 * `t` is time in seconds; motion is a blend of slow sines so it breathes rather than jitters.
 */
const tongue = (h: number, w: number, lean: number) =>
  `M${-w} 0 C${-w} ${-h * 0.35} ${-w * 0.2 + lean * 0.4} ${-h * 0.6} ${lean} ${-h} C${w * 0.3 + lean * 0.4} ${-h * 0.6} ${w} ${-h * 0.35} ${w} 0 Z`;

export const SacredFire: React.FC<{ x: number; y: number; scale?: number; t?: number }> = ({ x, y, scale = 1, t = 0 }) => {
  const layers = [
    { color: palette.fireOuter, h: 150, w: 44, spread: 34 },
    { color: palette.fireMid, h: 112, w: 32, spread: 24 },
    { color: palette.fireCore, h: 70, w: 18, spread: 14 },
  ];
  return (
    <g transform={`translate(${x} ${y}) scale(${scale})`}>
      <defs>
        <radialGradient id="fire-glow">
          <stop offset="0" stopColor="#FFC76A" stopOpacity={0.6} />
          <stop offset="0.5" stopColor="#FF9A3C" stopOpacity={0.22} />
          <stop offset="1" stopColor="#FF9A3C" stopOpacity={0} />
        </radialGradient>
      </defs>
      <ellipse cx={0} cy={-70} rx={200} ry={170} fill="url(#fire-glow)" />
      {layers.map((l, li) => (
        <g key={li}>
          {[-1, 0, 1].map((k) => {
            const phase = li * 1.3 + k * 2.1;
            const h = l.h * (k === 0 ? 1 : 0.72) * (1 + 0.08 * Math.sin(t * 5.1 + phase) + 0.05 * Math.sin(t * 8.3 + phase * 2));
            const lean = 8 * Math.sin(t * 2.7 + phase) + k * 10;
            return <path key={k} d={tongue(h, l.w * (k === 0 ? 1 : 0.8), lean)} transform={`translate(${k * l.spread} 0)`} fill={l.color} />;
          })}
        </g>
      ))}
      {/* embers */}
      {new Array(9).fill(0).map((_, i) => {
        const life = ((t * 0.6 + random(`em-${i}`)) % 1 + 1) % 1;
        const ex = (random(`ex-${i}`) - 0.5) * 80 + Math.sin(t * 2 + i) * 10 * life;
        const ey = -60 - life * 240;
        return <circle key={i} cx={ex} cy={ey} r={2.4 * (1 - life) + 0.8} fill={palette.goldPale} opacity={1 - life} />;
      })}
    </g>
  );
};

/** Soft rising smoke — broad translucent strokes that drift and thin out. */
export const Smoke: React.FC<{ x: number; y: number; t?: number; height?: number }> = ({ x, y, t = 0, height = 420 }) => (
  <g opacity={0.5}>
    {[0, 1, 2].map((i) => {
      const drift = Math.sin(t * 0.6 + i * 2) * 26;
      const d = `M${x + (i - 1) * 16} ${y} C${x - 40 + drift} ${y - height * 0.3} ${x + 50 - drift} ${y - height * 0.6} ${x + drift * 1.5 + (i - 1) * 30} ${y - height}`;
      return (
        <path key={i} d={d} fill="none" stroke="#FBF3E4" strokeWidth={22 - i * 6} strokeLinecap="round" opacity={0.28 - i * 0.06} />
      );
    })}
  </g>
);
